{
  "plan": {
    "name": "Câu 1 - CRUD sách",
    "description": "Kiểm tra POST/GET sách",
    "sequenceOrder": 1,
    "weight": 1
  },
  "steps": [
    {
      "stepOrder": 1,
      "name": "POST /api/books trả 201",
      "stepType": "HTTP_REQUEST",
      "weight": 2,
      "timeoutMs": 15000,
      "required": true,
      "config": {
        "method": "POST",
        "path": "/api/books",
        "headers": {
          "Content-Type": "application/json"
        },
        "body": {
          "title": "Effective Java",
          "price": 100
        },
        "expected_status": 201
      },
      "expectedResult": {
        "status": 201
      }
    },
    {
      "stepOrder": 2,
      "name": "GET /api/books trả 1 phần tử",
      "stepType": "HTTP_REQUEST",
      "weight": 1,
      "timeoutMs": 15000,
      "required": true,
      "config": {
        "method": "GET",
        "path": "/api/books",
        "expected_status": 200,
        "assertions": [
          {
            "kind": "json_path_equals",
            "path": "$[0].title",
            "equals": "Effective Java"
          }
        ]
      },
      "expectedResult": {
        "status": 200
      }
    },
    {
      "stepOrder": 3,
      "name": "DB có đúng 1 dòng",
      "stepType": "DB_QUERY",
      "weight": 1,
      "timeoutMs": 15000,
      "required": true,
      "config": {
        "connection": {
          "db_service": "db",
          "db_port": 5432,
          "db_type": "postgres",
          "database": "app",
          "username": "app",
          "password": "app"
        },
        "query": "SELECT COUNT(*) AS c FROM books",
        "expected": {
          "row_count": 1
        }
      },
      "expectedResult": {
        "row_count": 1
      }
    }
  ]
}

{
  "name": "Câu 2 - Tìm kiếm theo giá",
  "description": "Cập nhật mô tả",
  "sequenceOrder": 2,
  "weight": 2
}

